function hdProbe(u, ms) {
  if (!/^https?:\/\//i.test(String(u || '')) || /\.(?:zip|rar)(?:[?#]|$)/i.test(String(u || ''))) return Promise.resolve({ ok: false, st: 0 });
  // URL shape is not proof; do not resurrect a failed response with an
